BEGIN;

-- ============================================================
-- TEAM MEMORY: CONSOLIDATED DEVELOPMENT BASELINE RESET
--
-- Deletes existing data in these eight tables, including vector memories.
-- Intended only for a fresh/disposable LOCAL development database.
-- Never run against the hosted project or real team data. The non-destructive
-- hosted proposal is generated by backend/app/schema_upgrade.py for approval.
-- ============================================================

CREATE SCHEMA IF NOT EXISTS extensions;

CREATE EXTENSION IF NOT EXISTS vector
WITH SCHEMA extensions;

-- Fail clearly if an existing vector installation uses another schema.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_catalog.pg_extension AS e
        JOIN pg_catalog.pg_namespace AS n ON n.oid = e.extnamespace
        WHERE e.extname = 'vector' AND n.nspname = 'extensions'
    ) THEN
        RAISE EXCEPTION 'The vector extension must be installed in the extensions schema';
    END IF;
END;
$$;

-- Remove the previous search definition before resetting its source table.
DROP FUNCTION IF EXISTS public.search_memories(
    UUID, UUID, extensions.vector, INTEGER
);
DROP FUNCTION IF EXISTS public.store_message_extraction(UUID, TEXT, JSONB, JSONB);
DROP FUNCTION IF EXISTS public.claim_memory_embeddings(UUID, UUID[], INTEGER);
DROP FUNCTION IF EXISTS public.finish_memory_embedding(UUID, UUID, UUID, UUID, TEXT, extensions.vector, TEXT);

DROP TABLE IF EXISTS
    public.memories,
    public.reminder_deliveries,
    public.room_members,
    public.commitments,
    public.decisions,
    public.messages,
    public.rooms,
    public.tenants;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ============================================================
-- 1. TEAMS AND SWITCH ROOMS
-- ============================================================

CREATE TABLE public.tenants (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL CHECK (btrim(name) <> ''),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE public.rooms (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL
        REFERENCES public.tenants(id) ON DELETE RESTRICT,

    switch_room_id TEXT NOT NULL UNIQUE
        CHECK (btrim(switch_room_id) <> ''),

    name TEXT,
    platform TEXT
        CHECK (platform IN ('discord', 'slack', 'teams')),
    workspace_id TEXT,
    channel_id TEXT,

    enabled BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (tenant_id, id)
);

-- Backend-managed room permissions.
-- Populate only from trusted onboarding or admin actions.
CREATE TABLE public.room_members (
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    switch_user_id TEXT NOT NULL
        CHECK (btrim(switch_user_id) <> ''),

    role TEXT NOT NULL DEFAULT 'member'
        CHECK (role IN ('member', 'approver', 'admin')),

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, room_id, switch_user_id),

    FOREIGN KEY (tenant_id, room_id)
        REFERENCES public.rooms(tenant_id, id)
        ON DELETE RESTRICT
);

-- ============================================================
-- 2. MESSAGES AND EXTRACTION PROCESSING
-- ============================================================

CREATE TABLE public.messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,

    switch_message_id TEXT NOT NULL
        CHECK (btrim(switch_message_id) <> ''),
    switch_author_id TEXT,

    platform TEXT
        CHECK (platform IN ('discord', 'slack', 'teams')),
    workspace_id TEXT,
    channel_id TEXT,
    external_message_id TEXT,
    external_author_id TEXT,
    thread_id TEXT,

    author_name TEXT,
    body TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    extraction_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            extraction_status IN (
                'pending', 'processing', 'completed', 'failed'
            )
        ),

    extraction_attempts INTEGER NOT NULL DEFAULT 0
        CHECK (extraction_attempts >= 0),
    extraction_next_attempt_at TIMESTAMPTZ DEFAULT now(),
    extraction_lease_until TIMESTAMPTZ,
    extraction_claim_token UUID,
    extraction_completed_at TIMESTAMPTZ,

    -- Store sanitized error codes, never credentials or raw errors.
    extraction_error_code TEXT,

    FOREIGN KEY (tenant_id, room_id)
        REFERENCES public.rooms(tenant_id, id)
        ON DELETE RESTRICT,

    UNIQUE (tenant_id, room_id, switch_message_id),
    UNIQUE (tenant_id, room_id, id),

    CHECK (
        extraction_status <> 'completed'
        OR extraction_completed_at IS NOT NULL
    )
);

CREATE INDEX idx_messages_room_time
    ON public.messages (tenant_id, room_id, occurred_at DESC);

CREATE INDEX idx_messages_extraction_queue
    ON public.messages (extraction_next_attempt_at)
    WHERE extraction_status IN ('pending', 'failed');

CREATE INDEX idx_messages_extraction_lease
    ON public.messages (extraction_lease_until)
    WHERE extraction_status = 'processing';

-- Switch message IDs are the primary deduplication identity.
-- Original platform IDs are retained for evidence and lookups.
CREATE INDEX idx_messages_external_source
    ON public.messages (
        platform, workspace_id, channel_id, external_message_id
    );

-- ============================================================
-- 3. COMMITMENTS
-- ============================================================

CREATE TABLE public.commitments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    message_id UUID NOT NULL,

    -- Stable item key within a message's extraction result.
    extraction_key TEXT NOT NULL
        CHECK (btrim(extraction_key) <> ''),

    description TEXT NOT NULL,
    owner_name TEXT,
    owner_external_id TEXT,
    owner_switch_user_id TEXT,
    due_at TIMESTAMPTZ,

    approval_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            approval_status IN ('pending', 'approved', 'rejected')
        ),

    approval_by_switch_user_id TEXT,
    approval_at TIMESTAMPTZ,

    task_status TEXT NOT NULL DEFAULT 'not_started'
        CHECK (
            task_status IN (
                'not_started', 'in_progress', 'completed', 'cancelled'
            )
        ),

    completed_at TIMESTAMPTZ,
    next_reminder_at TIMESTAMPTZ,
    last_chased_at TIMESTAMPTZ,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    FOREIGN KEY (tenant_id, room_id, message_id)
        REFERENCES public.messages(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    UNIQUE (message_id, extraction_key),
    UNIQUE (tenant_id, room_id, id),

    CHECK (
        (task_status = 'completed' AND completed_at IS NOT NULL)
        OR
        (task_status <> 'completed' AND completed_at IS NULL)
    ),

    CHECK (
        approval_status = 'pending'
        OR (
            approval_by_switch_user_id IS NOT NULL
            AND approval_at IS NOT NULL
        )
    )
);

CREATE INDEX idx_commitments_room_created
    ON public.commitments (tenant_id, room_id, created_at DESC);

CREATE INDEX idx_commitments_message
    ON public.commitments (tenant_id, room_id, message_id);

CREATE INDEX idx_commitments_owner
    ON public.commitments (
        tenant_id, room_id, owner_switch_user_id
    );

CREATE INDEX idx_commitments_reminder_queue
    ON public.commitments (next_reminder_at)
    WHERE approval_status = 'approved'
      AND task_status IN ('not_started', 'in_progress');

-- ============================================================
-- 4. DECISIONS
-- ============================================================

CREATE TABLE public.decisions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    message_id UUID NOT NULL,

    extraction_key TEXT NOT NULL
        CHECK (btrim(extraction_key) <> ''),

    topic TEXT,
    summary TEXT NOT NULL,

    approval_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            approval_status IN ('pending', 'approved', 'rejected')
        ),

    approval_by_switch_user_id TEXT,
    approval_at TIMESTAMPTZ,

    decision_status TEXT NOT NULL DEFAULT 'active'
        CHECK (
            decision_status IN ('active', 'superseded', 'revoked')
        ),

    supersedes_decision_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (message_id, extraction_key),
    UNIQUE (tenant_id, room_id, id),

    FOREIGN KEY (tenant_id, room_id, message_id)
        REFERENCES public.messages(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    FOREIGN KEY (tenant_id, room_id, supersedes_decision_id)
        REFERENCES public.decisions(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    CHECK (
        supersedes_decision_id IS NULL
        OR supersedes_decision_id <> id
    ),

    CHECK (
        approval_status = 'pending'
        OR (
            approval_by_switch_user_id IS NOT NULL
            AND approval_at IS NOT NULL
        )
    )
);

CREATE INDEX idx_decisions_room_created
    ON public.decisions (tenant_id, room_id, created_at DESC);

CREATE INDEX idx_decisions_message
    ON public.decisions (tenant_id, room_id, message_id);

CREATE INDEX idx_decisions_supersedes
    ON public.decisions (
        tenant_id, room_id, supersedes_decision_id
    )
    WHERE supersedes_decision_id IS NOT NULL;

-- ============================================================
-- VECTOR MEMORY STORAGE
-- ============================================================

-- Searchable facts and summaries retain their original message evidence.
-- Commitment deadlines/status remain in commitments.
-- Decision approval/status remain in decisions.
-- FastAPI must synchronize these summaries with their structured records.
CREATE TABLE public.memories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    message_id UUID NOT NULL,

    memory_type TEXT NOT NULL
        CHECK (memory_type IN ('fact', 'decision', 'commitment')),
    extraction_key TEXT NOT NULL
        CHECK (btrim(extraction_key) <> ''),
    content TEXT NOT NULL CHECK (btrim(content) <> ''),

    -- Generate embeddings in the backend, using the same model for queries.
    -- NULL embeddings are allowed while generation is pending.
    embedding extensions.vector(384),
    embedding_model TEXT NOT NULL DEFAULT 'Supabase/gte-small'
        CHECK (embedding_model = 'Supabase/gte-small'),
    -- EMBEDDING_COLUMNS_BEGIN
    content_hash TEXT NOT NULL,
    embedding_recipe TEXT NOT NULL DEFAULT '93b36ff09519291b77d6000d2e86bd8565378086:onnx-fp32:masked-mean:l2:v1'
        CHECK (embedding_recipe = '93b36ff09519291b77d6000d2e86bd8565378086:onnx-fp32:masked-mean:l2:v1'),
    embedding_content_hash TEXT,
    embedding_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (embedding_status IN ('pending','processing','completed','failed')),
    embedding_attempts INTEGER NOT NULL DEFAULT 0 CHECK (embedding_attempts >= 0),
    embedding_next_attempt_at TIMESTAMPTZ DEFAULT now(),
    embedding_lease_until TIMESTAMPTZ,
    embedding_claim_token UUID,
    embedding_completed_at TIMESTAMPTZ,
    embedding_error_code TEXT,
    -- EMBEDDING_COLUMNS_END

    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    FOREIGN KEY (tenant_id, room_id, message_id)
        REFERENCES public.messages(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    UNIQUE (message_id, memory_type, extraction_key),
    CONSTRAINT memories_embedding_state_check CHECK ((embedding_status = 'completed') = (embedding IS NOT NULL)),
    CONSTRAINT memories_embedding_content_check CHECK (embedding_status <> 'completed' OR (
        embedding_content_hash = content_hash AND embedding_content_hash IS NOT NULL
        AND embedding_completed_at IS NOT NULL
        AND extensions.vector_norm(embedding) > 0))
);

CREATE INDEX idx_memories_room
    ON public.memories (tenant_id, room_id);

CREATE INDEX idx_memories_source_message
    ON public.memories (tenant_id, room_id, message_id);
CREATE INDEX idx_memories_embedding_queue
    ON public.memories (tenant_id, room_id, embedding_next_attempt_at)
    WHERE active AND embedding_status IN ('pending','failed');
CREATE INDEX idx_memories_embedding_lease
    ON public.memories (embedding_lease_until)
    WHERE embedding_status = 'processing';

-- An edited memory must not be searched using its previous text's embedding.
-- The backend regenerates the embedding after updating content.
CREATE OR REPLACE FUNCTION public.clear_stale_memory_embedding()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
    NEW.content_hash = pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(NEW.content, 'UTF8')), 'hex');
    IF TG_OP = 'INSERT' THEN
        IF NEW.embedding IS NOT NULL THEN
            NEW.embedding_status = 'completed';
            NEW.embedding_content_hash = NEW.content_hash;
            NEW.embedding_completed_at = now();
        END IF;
    ELSIF NEW.content IS DISTINCT FROM OLD.content THEN
        NEW.embedding = NULL;
        NEW.embedding_content_hash = NULL;
        NEW.embedding_status = 'pending';
        NEW.embedding_attempts = 0;
        NEW.embedding_next_attempt_at = now();
        NEW.embedding_lease_until = NULL;
        NEW.embedding_claim_token = NULL;
        NEW.embedding_completed_at = NULL;
        NEW.embedding_error_code = NULL;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER memories_clear_stale_embedding
BEFORE INSERT OR UPDATE OF content ON public.memories
FOR EACH ROW EXECUTE FUNCTION public.clear_stale_memory_embedding();

-- Exact vector search is sufficient for the initial small dataset.
-- Add an approximate vector index only after measuring search performance.
CREATE FUNCTION public.search_memories(
    p_tenant_id UUID,
    p_room_id UUID,
    p_embedding extensions.vector(384),
    p_limit INTEGER DEFAULT 5
)
RETURNS TABLE (
    id UUID,
    message_id UUID,
    memory_type TEXT,
    content TEXT,
    similarity DOUBLE PRECISION
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
    SELECT
        m.id,
        m.message_id,
        m.memory_type,
        m.content,
        1 - (
            m.embedding OPERATOR(extensions.<=>) p_embedding
        ) AS similarity
    FROM public.memories AS m
    WHERE p_embedding IS NOT NULL
      AND m.tenant_id = p_tenant_id
      AND m.room_id = p_room_id
      AND m.active = true
      AND m.embedding IS NOT NULL
      AND m.embedding_status = 'completed'
      AND m.embedding_content_hash = m.content_hash
      AND m.embedding_recipe = '93b36ff09519291b77d6000d2e86bd8565378086:onnx-fp32:masked-mean:l2:v1'
    ORDER BY
        m.embedding OPERATOR(extensions.<=>) p_embedding
    LIMIT greatest(1, least(coalesce(p_limit, 5), 50));
$$;

-- ATOMIC_STORAGE_BEGIN
CREATE FUNCTION public.store_message_extraction(
    p_tenant_id uuid, p_switch_room_id text, p_source jsonb, p_items jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE
    room_uuid uuid;
    message_uuid uuid;
    existing_status text;
    item jsonb;
    counts jsonb;
BEGIN
    SELECT id INTO room_uuid FROM public.rooms
    WHERE tenant_id = p_tenant_id AND switch_room_id = p_switch_room_id AND enabled
    FOR SHARE;
    IF room_uuid IS NULL THEN
        RAISE EXCEPTION 'unauthorized_room' USING ERRCODE = '42501';
    END IF;
    IF nullif(btrim(p_source->>'switch_message_id'), '') IS NULL
       OR jsonb_typeof(p_items->'commitments') IS DISTINCT FROM 'array'
       OR jsonb_typeof(p_items->'decisions') IS DISTINCT FROM 'array'
       OR jsonb_typeof(p_items->'memories') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_items->'memories') = 0 THEN
        RAISE EXCEPTION 'invalid_extraction' USING ERRCODE = '22023';
    END IF;
    -- Serialize replays even across API hosts; hash collisions only serialize extra work.
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_tenant_id::text || ':' || room_uuid::text || ':' || (p_source->>'switch_message_id'), 0));
    SELECT id, extraction_status INTO message_uuid, existing_status
    FROM public.messages WHERE tenant_id = p_tenant_id AND room_id = room_uuid
      AND switch_message_id = p_source->>'switch_message_id' FOR UPDATE;

    IF existing_status IS DISTINCT FROM 'completed' THEN
        IF message_uuid IS NULL THEN
            INSERT INTO public.messages (
                tenant_id, room_id, switch_message_id, switch_author_id, platform,
                workspace_id, channel_id, external_message_id, external_author_id,
                thread_id, author_name, body, occurred_at
            ) VALUES (
                p_tenant_id, room_uuid, p_source->>'switch_message_id', p_source->>'switch_author_id',
                p_source->>'platform', p_source->>'workspace_id', p_source->>'channel_id',
                p_source->>'external_message_id', p_source->>'external_author_id',
                p_source->>'thread_id', p_source->>'author_name', p_source->>'body',
                (p_source->>'occurred_at')::timestamptz
            ) RETURNING id INTO message_uuid;
        END IF;
        FOR item IN SELECT value FROM jsonb_array_elements(p_items->'commitments') LOOP
            INSERT INTO public.commitments (tenant_id, room_id, message_id, extraction_key,
                                           description, owner_name, due_at)
            VALUES (p_tenant_id, room_uuid, message_uuid, item->>'extraction_key',
                    item->>'description', item->>'owner_name', (item->>'due_at')::timestamptz)
            ON CONFLICT (message_id, extraction_key) DO NOTHING;
        END LOOP;
        FOR item IN SELECT value FROM jsonb_array_elements(p_items->'decisions') LOOP
            INSERT INTO public.decisions (tenant_id, room_id, message_id, extraction_key, topic, summary)
            VALUES (p_tenant_id, room_uuid, message_uuid, item->>'extraction_key', item->>'topic', item->>'summary')
            ON CONFLICT (message_id, extraction_key) DO NOTHING;
        END LOOP;
        FOR item IN SELECT value FROM jsonb_array_elements(p_items->'memories') LOOP
            INSERT INTO public.memories (tenant_id, room_id, message_id, extraction_key, memory_type, content)
            VALUES (p_tenant_id, room_uuid, message_uuid, item->>'extraction_key', item->>'memory_type', item->>'content')
            ON CONFLICT (message_id, memory_type, extraction_key) DO NOTHING;
        END LOOP;
        UPDATE public.messages SET extraction_status = 'completed', extraction_completed_at = now(),
            extraction_error_code = NULL, extraction_lease_until = NULL, extraction_claim_token = NULL
        WHERE id = message_uuid;
    END IF;
    SELECT jsonb_build_object(
        'messages', 1,
        'commitments', (SELECT count(*) FROM public.commitments WHERE message_id = message_uuid),
        'decisions', (SELECT count(*) FROM public.decisions WHERE message_id = message_uuid),
        'memories', (SELECT count(*) FROM public.memories WHERE message_id = message_uuid)
    ) INTO counts;
    RETURN counts;
END;
$$;

REVOKE ALL ON FUNCTION public.store_message_extraction(uuid,text,jsonb,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_message_extraction(uuid,text,jsonb,jsonb) TO service_role;
-- ATOMIC_STORAGE_END

-- EMBEDDING_WORK_BEGIN
-- Memory rows themselves are durable, versioned embedding jobs. Claim leases recover
-- after a process crash; claim tokens + hashes prevent stale results after edits.
CREATE FUNCTION public.claim_memory_embeddings(
    p_tenant_id UUID, p_room_ids UUID[], p_limit INTEGER DEFAULT 8
) RETURNS TABLE (
    id UUID, tenant_id UUID, room_id UUID, message_id UUID,
    content TEXT, content_hash TEXT, claim_token UUID
)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
BEGIN
    UPDATE public.memories AS m SET embedding_status='failed',
        embedding_error_code='lease_exhausted', embedding_lease_until=NULL, embedding_claim_token=NULL
    WHERE m.tenant_id=p_tenant_id AND m.room_id=ANY(p_room_ids)
      AND m.embedding_status='processing' AND m.embedding_attempts>=3
      AND m.embedding_lease_until<=now();
    RETURN QUERY
    WITH candidates AS (
        SELECT m.id FROM public.memories AS m
        JOIN public.rooms AS r ON r.id=m.room_id AND r.tenant_id=m.tenant_id AND r.enabled
        WHERE m.tenant_id=p_tenant_id AND m.room_id=ANY(p_room_ids) AND m.active
          AND m.embedding_attempts<3
          AND ((m.embedding_status IN ('pending','failed') AND m.embedding_next_attempt_at<=now())
               OR (m.embedding_status='processing' AND m.embedding_lease_until<=now()))
        ORDER BY m.created_at,m.id
        LIMIT greatest(1,least(coalesce(p_limit,8),8)) FOR UPDATE OF m SKIP LOCKED
    )
    UPDATE public.memories AS m SET embedding_status='processing',
        embedding_attempts=m.embedding_attempts+1,
        embedding_lease_until=now()+interval '5 minutes', embedding_claim_token=gen_random_uuid(),
        embedding_error_code=NULL
    FROM candidates AS c WHERE m.id=c.id
    RETURNING m.id,m.tenant_id,m.room_id,m.message_id,m.content,m.content_hash,m.embedding_claim_token;
END;
$$;

CREATE FUNCTION public.finish_memory_embedding(
    p_memory_id UUID, p_tenant_id UUID, p_room_id UUID, p_claim_token UUID,
    p_content_hash TEXT, p_embedding extensions.vector(384), p_error_code TEXT DEFAULT NULL
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE changed INTEGER;
BEGIN
    IF p_error_code IS NOT NULL THEN
        IF p_error_code NOT IN ('input_too_long','invalid_input','invalid_vector','model_not_installed',
            'model_checksum_failed','dependencies_missing','inference_failed','worker_interrupted') THEN
            RAISE EXCEPTION 'invalid_embedding_error' USING ERRCODE='22023';
        END IF;
    ELSIF p_embedding IS NULL OR extensions.vector_dims(p_embedding)<>384
        OR abs(extensions.vector_norm(p_embedding)-1)>0.001
        OR NOT (extensions.vector_norm(p_embedding)>0) THEN
        RAISE EXCEPTION 'invalid_embedding_vector' USING ERRCODE='22023';
    END IF;
    UPDATE public.memories AS m SET
        embedding=CASE WHEN p_error_code IS NULL THEN p_embedding ELSE NULL END,
        embedding_content_hash=CASE WHEN p_error_code IS NULL THEN p_content_hash ELSE NULL END,
        embedding_status=CASE WHEN p_error_code IS NULL THEN 'completed' ELSE 'failed' END,
        embedding_completed_at=CASE WHEN p_error_code IS NULL THEN now() ELSE NULL END,
        embedding_error_code=p_error_code,
        embedding_attempts=CASE WHEN p_error_code IN ('input_too_long','invalid_input') THEN 3 ELSE m.embedding_attempts END,
        embedding_next_attempt_at=CASE WHEN p_error_code IS NULL THEN NULL ELSE now()+interval '30 seconds' END,
        embedding_lease_until=NULL, embedding_claim_token=NULL
    WHERE m.id=p_memory_id AND m.tenant_id=p_tenant_id AND m.room_id=p_room_id
      AND m.content_hash=p_content_hash AND m.embedding_claim_token=p_claim_token
      AND m.embedding_status='processing'
      AND EXISTS (SELECT 1 FROM public.rooms AS r WHERE r.id=m.room_id AND r.tenant_id=m.tenant_id AND r.enabled);
    GET DIAGNOSTICS changed = ROW_COUNT;
    RETURN changed=1;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_memory_embeddings(UUID,UUID[],INTEGER) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.finish_memory_embedding(UUID,UUID,UUID,UUID,TEXT,extensions.vector,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_memory_embeddings(UUID,UUID[],INTEGER) TO service_role;
GRANT EXECUTE ON FUNCTION public.finish_memory_embedding(UUID,UUID,UUID,UUID,TEXT,extensions.vector,TEXT) TO service_role;
-- EMBEDDING_WORK_END

-- ============================================================
-- 5. REMINDER DELIVERY TRACKING
-- ============================================================

CREATE TABLE public.reminder_deliveries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    commitment_id UUID NOT NULL,

    scheduled_for TIMESTAMPTZ NOT NULL,

    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            status IN ('pending', 'sending', 'sent', 'failed')
        ),

    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at TIMESTAMPTZ DEFAULT now(),
    lease_until TIMESTAMPTZ,
    claim_token UUID,

    switch_reply_message_id TEXT,
    sent_at TIMESTAMPTZ,
    error_code TEXT,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (commitment_id, scheduled_for),

    FOREIGN KEY (tenant_id, room_id, commitment_id)
        REFERENCES public.commitments(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    CHECK (status <> 'sent' OR sent_at IS NOT NULL)
);

CREATE INDEX idx_reminder_deliveries_queue
    ON public.reminder_deliveries (next_attempt_at)
    WHERE status IN ('pending', 'failed');

CREATE INDEX idx_reminder_deliveries_lease
    ON public.reminder_deliveries (lease_until)
    WHERE status = 'sending';

CREATE INDEX idx_reminder_deliveries_room
    ON public.reminder_deliveries (tenant_id, room_id);

CREATE INDEX idx_reminder_deliveries_commitment
    ON public.reminder_deliveries (tenant_id, room_id, commitment_id);

-- ============================================================
-- 6. AUTOMATIC UPDATE TIMESTAMPS
-- ============================================================

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER commitments_set_updated_at
BEFORE UPDATE ON public.commitments
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER decisions_set_updated_at
BEFORE UPDATE ON public.decisions
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER reminder_deliveries_set_updated_at
BEFORE UPDATE ON public.reminder_deliveries
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- ============================================================
-- 7. BACKEND-ONLY DATABASE ACCESS
-- ============================================================

-- Required even if this migration created the extensions schema itself.
GRANT USAGE ON SCHEMA extensions TO service_role;

ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.room_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.memories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commitments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reminder_deliveries ENABLE ROW LEVEL SECURITY;

REVOKE ALL PRIVILEGES ON TABLE
    public.memories,
    public.tenants,
    public.rooms,
    public.room_members,
    public.messages,
    public.commitments,
    public.decisions,
    public.reminder_deliveries
FROM PUBLIC, anon, authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE
    public.memories,
    public.tenants,
    public.rooms,
    public.room_members,
    public.messages,
    public.commitments,
    public.decisions,
    public.reminder_deliveries
TO service_role;

REVOKE ALL ON FUNCTION public.search_memories(
    UUID, UUID, extensions.vector, INTEGER
) FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.search_memories(
    UUID, UUID, extensions.vector, INTEGER
) TO service_role;

COMMIT;

-- Expect eight rows with rls_enabled = true.
SELECT tablename, rowsecurity AS rls_enabled
FROM pg_tables
WHERE schemaname = 'public'
  AND tablename IN (
      'tenants',
      'rooms',
      'room_members',
      'messages',
      'memories',
      'commitments',
      'decisions',
      'reminder_deliveries'
  )
ORDER BY tablename;
-- Additive document module. Never replay the destructive core baseline remotely.
BEGIN;
CREATE TABLE public.documents (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    source_key text NOT NULL CHECK (length(source_key) BETWEEN 1 AND 200),
    source_type text NOT NULL CHECK (source_type IN ('markdown','text')),
    title text NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
    created_by text NOT NULL,
    latest_version integer NOT NULL DEFAULT 0 CHECK (latest_version >= 0),
    published_version_id uuid,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id,room_id,source_key),
    UNIQUE (tenant_id,room_id,id),
    FOREIGN KEY (tenant_id,room_id) REFERENCES public.rooms(tenant_id,id) ON DELETE RESTRICT
);
CREATE TABLE public.document_versions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_number integer NOT NULL CHECK (version_number > 0),
    title text NOT NULL,
    filename text NOT NULL,
    source_text text NOT NULL CHECK (octet_length(source_text) BETWEEN 1 AND 262144),
    content_hash text NOT NULL CHECK (content_hash = encode(sha256(convert_to(source_text,'UTF8')),'hex')),
    recipe text NOT NULL,
    model_recipe text NOT NULL,
    status text NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','completed','failed')),
    error text CHECK (error IN ('model_not_installed','model_checksum_failed','dependencies_missing',
        'invalid_vector','invalid_input','input_too_long','inference_failed','lease_exhausted','version_superseded')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (document_id,version_number),
    UNIQUE (tenant_id,room_id,document_id,id),
    FOREIGN KEY (tenant_id,room_id,document_id) REFERENCES public.documents(tenant_id,room_id,id) ON DELETE RESTRICT
);
ALTER TABLE public.documents ADD CONSTRAINT documents_published_version_fk
    FOREIGN KEY (tenant_id,room_id,id,published_version_id)
    REFERENCES public.document_versions(tenant_id,room_id,document_id,id) ON DELETE RESTRICT;
CREATE TABLE public.document_chunks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_id uuid NOT NULL,
    position integer NOT NULL CHECK (position >= 0),
    text text NOT NULL CHECK (length(text)>0),
    content_hash text NOT NULL CHECK (content_hash=encode(sha256(convert_to(text,'UTF8')),'hex')),
    start_char integer NOT NULL CHECK (start_char>=0),
    end_char integer NOT NULL CHECK (end_char>start_char),
    start_line integer NOT NULL CHECK (start_line>0),
    end_line integer NOT NULL CHECK (end_line>=start_line),
    section text,
    model_recipe text NOT NULL,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','failed')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 3),
    error text CHECK (error IN ('model_not_installed','model_checksum_failed','dependencies_missing',
        'invalid_vector','invalid_input','input_too_long','inference_failed','lease_exhausted','version_superseded')),
    retry_at timestamptz NOT NULL DEFAULT now(),
    lease_until timestamptz,
    claim_token uuid,
    embedding extensions.vector(384),
    embedding_content_hash text,
    CHECK ((status='completed') = (embedding IS NOT NULL)),
    CHECK (status<>'completed' OR embedding_content_hash IS NOT DISTINCT FROM content_hash),
    UNIQUE (version_id,position),
    FOREIGN KEY (tenant_id,room_id,document_id,version_id)
        REFERENCES public.document_versions(tenant_id,room_id,document_id,id) ON DELETE RESTRICT
);
CREATE TABLE public.document_imports (
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    import_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_id uuid NOT NULL,
    request_hash text NOT NULL,
    PRIMARY KEY (tenant_id,import_id),
    FOREIGN KEY (tenant_id,room_id,document_id,version_id)
        REFERENCES public.document_versions(tenant_id,room_id,document_id,id) ON DELETE RESTRICT
);
CREATE INDEX document_chunks_queue ON public.document_chunks(retry_at)
    WHERE status IN ('pending','failed');
CREATE INDEX document_chunks_lease ON public.document_chunks(lease_until) WHERE status='processing';
CREATE INDEX document_chunks_scope ON public.document_chunks(tenant_id,room_id,version_id);
-- Exact cosine search for the bounded initial corpus. No unbenchmarked ANN claim.
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_imports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.documents,public.document_versions,public.document_chunks,public.document_imports FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documents,public.document_versions,public.document_chunks,public.document_imports TO service_role;

CREATE FUNCTION public.document_operation(p_tenant_id uuid,p_room_ids uuid[],p_operation text,p_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,extensions AS $$
DECLARE
    d public.documents%ROWTYPE;
    v public.document_versions%ROWTYPE;
    c public.document_chunks%ROWTYPE;
    prior public.document_imports%ROWTYPE;
    piece jsonb;
    result jsonb;
    duplicate boolean := false;
    document_uuid uuid;
    vector_value extensions.vector(384);
    error_value text;
BEGIN
    IF p_tenant_id IS NULL OR coalesce(cardinality(p_room_ids),0)=0 OR
        EXISTS (SELECT 1 FROM unnest(p_room_ids) room WHERE NOT EXISTS (
            SELECT 1 FROM public.rooms r WHERE r.id=room AND r.tenant_id=p_tenant_id AND r.enabled)) THEN
        RAISE EXCEPTION 'document_scope_denied' USING ERRCODE='42501';
    END IF;
    IF p_operation='import_status' THEN
        SELECT * INTO prior FROM public.document_imports WHERE tenant_id=p_tenant_id AND room_id=ANY(p_room_ids)
            AND import_id=(p_data->>'import_id')::uuid;
        IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
        SELECT * INTO v FROM public.document_versions WHERE id=prior.version_id;
        RETURN jsonb_build_object('import_id',prior.import_id,'document_id',prior.document_id,'version_id',v.id,
            'version_number',v.version_number,'status',v.status,'duplicate',true);
    ELSIF p_operation='import' THEN
        -- Serialize both idempotency identity and stable source identity, in fixed order.
        PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||(p_data->>'import_id'),0));
        PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||(p_data->>'room_id')||':'||(p_data->>'source_key'),1));
        SELECT * INTO prior FROM public.document_imports WHERE tenant_id=p_tenant_id AND import_id=(p_data->>'import_id')::uuid;
        IF FOUND THEN
            IF prior.request_hash<>p_data->>'request_hash' THEN
                RAISE EXCEPTION 'document_version_conflict' USING ERRCODE='40001';
            END IF;
            IF NOT prior.room_id=ANY(p_room_ids) THEN RAISE EXCEPTION 'document_scope_denied' USING ERRCODE='42501'; END IF;
            SELECT * INTO d FROM public.documents WHERE id=prior.document_id;
            SELECT * INTO v FROM public.document_versions WHERE id=prior.version_id;
            duplicate:=true;
        ELSE
            IF NOT (p_data->>'room_id')::uuid=ANY(p_room_ids) OR jsonb_array_length(p_data->'chunks') NOT BETWEEN 1 AND 1024 THEN
                RAISE EXCEPTION 'document_invalid_import' USING ERRCODE='22023';
            END IF;
            SELECT * INTO d FROM public.documents WHERE tenant_id=p_tenant_id AND room_id=(p_data->>'room_id')::uuid
                AND source_key=p_data->>'source_key' FOR UPDATE;
            IF coalesce(d.latest_version,0)<>(p_data->>'expected_version')::integer OR d.active=false
                OR (d.id IS NOT NULL AND d.source_type<>p_data->>'source_type') THEN
                RAISE EXCEPTION 'document_version_conflict' USING ERRCODE='40001';
            END IF;
            IF d.id IS NULL THEN
                INSERT INTO public.documents(tenant_id,room_id,source_key,source_type,title,created_by)
                VALUES(p_tenant_id,(p_data->>'room_id')::uuid,p_data->>'source_key',p_data->>'source_type',p_data->>'title',p_data->>'actor') RETURNING * INTO d;
            END IF;
            SELECT * INTO v FROM public.document_versions WHERE document_id=d.id AND version_number=d.latest_version;
            duplicate:=v.id IS NOT NULL AND v.content_hash=p_data->>'content_hash' AND v.recipe=p_data->>'recipe'
                AND v.model_recipe=p_data->>'model_recipe' AND v.title=p_data->>'title';
            IF NOT duplicate THEN
                UPDATE public.document_chunks x SET status='failed',error='version_superseded',claim_token=NULL,lease_until=NULL
                    FROM public.document_versions z WHERE x.version_id=z.id AND z.document_id=d.id AND z.status<>'completed'
                    AND x.status<>'completed';
                UPDATE public.document_versions SET status='failed',error='version_superseded'
                    WHERE document_id=d.id AND status<>'completed';
                INSERT INTO public.document_versions(tenant_id,room_id,document_id,version_number,title,filename,source_text,content_hash,recipe,model_recipe)
                VALUES(p_tenant_id,d.room_id,d.id,d.latest_version+1,p_data->>'title',p_data->>'filename',p_data->>'source_text',
                    p_data->>'content_hash',p_data->>'recipe',p_data->>'model_recipe') RETURNING * INTO v;
                FOR piece IN SELECT value FROM jsonb_array_elements(p_data->'chunks') LOOP
                    -- Locations must describe an exact slice of the preserved source.
                    IF substring(v.source_text FROM (piece->>'start_char')::integer+1
                        FOR (piece->>'end_char')::integer-(piece->>'start_char')::integer)<>piece->>'text' THEN
                        RAISE EXCEPTION 'document_invalid_chunk' USING ERRCODE='22023';
                    END IF;
                    INSERT INTO public.document_chunks(tenant_id,room_id,document_id,version_id,position,text,content_hash,
                        start_char,end_char,start_line,end_line,section,model_recipe)
                    VALUES(p_tenant_id,d.room_id,d.id,v.id,(piece->>'position')::integer,piece->>'text',piece->>'content_hash',
                        (piece->>'start_char')::integer,(piece->>'end_char')::integer,(piece->>'start_line')::integer,
                        (piece->>'end_line')::integer,piece->>'section',v.model_recipe);
                END LOOP;
                UPDATE public.documents SET latest_version=v.version_number WHERE id=d.id RETURNING * INTO d;
            END IF;
            INSERT INTO public.document_imports VALUES(p_tenant_id,d.room_id,(p_data->>'import_id')::uuid,d.id,v.id,p_data->>'request_hash');
        END IF;
        RETURN jsonb_build_object('import_id',p_data->>'import_id','document_id',d.id,'version_id',v.id,
            'version_number',v.version_number,'status',v.status,'duplicate',duplicate);
    ELSIF p_operation='documents' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (
            SELECT * FROM public.documents WHERE tenant_id=p_tenant_id AND room_id=ANY(p_room_ids)
            ORDER BY id LIMIT least(greatest((p_data->>'limit')::integer,1),50) OFFSET least(greatest((p_data->>'offset')::integer,0),10000)) q;
        RETURN result;
    ELSIF p_operation='claim' THEN
        -- Lock documents before chunks, just as finish/import/archive do.
        FOR d IN SELECT * FROM public.documents WHERE tenant_id=p_tenant_id AND room_id=ANY(p_room_ids) AND active
            ORDER BY id FOR UPDATE SKIP LOCKED LOOP
            UPDATE public.document_chunks x SET status='failed',error='lease_exhausted',claim_token=NULL
                FROM public.document_versions z WHERE x.version_id=z.id AND z.document_id=d.id AND z.version_number=d.latest_version
                AND x.status='processing' AND x.attempts>=3 AND x.lease_until<=now();
            UPDATE public.document_versions z SET status='failed',error='lease_exhausted' WHERE z.document_id=d.id
                AND z.version_number=d.latest_version AND EXISTS(SELECT 1 FROM public.document_chunks x WHERE x.version_id=z.id AND x.error='lease_exhausted');
        END LOOP;
        WITH picked AS (
            SELECT x.id FROM public.document_chunks x JOIN public.document_versions z ON z.id=x.version_id
            JOIN public.documents a ON a.id=x.document_id
            WHERE a.tenant_id=p_tenant_id AND a.room_id=ANY(p_room_ids) AND a.active
                AND z.version_number=a.latest_version AND x.attempts<3
                AND ((x.status IN ('pending','failed') AND x.retry_at<=now()) OR (x.status='processing' AND x.lease_until<=now()))
            ORDER BY x.id LIMIT 4 FOR UPDATE OF x SKIP LOCKED
        ), updated AS (
            UPDATE public.document_chunks x SET status='processing',attempts=x.attempts+1,claim_token=gen_random_uuid(),
                lease_until=now()+interval '5 minutes',error=NULL FROM picked WHERE x.id=picked.id RETURNING x.*
        ) SELECT coalesce(jsonb_agg(to_jsonb(updated)-'embedding'),'[]') INTO result FROM updated;
        RETURN result;
    ELSIF p_operation='finish' THEN
        SELECT document_id INTO document_uuid FROM public.document_chunks WHERE id=(p_data->>'id')::uuid
            AND tenant_id=p_tenant_id AND room_id=ANY(p_room_ids);
        IF document_uuid IS NULL THEN RETURN 'false'; END IF;
        SELECT * INTO d FROM public.documents WHERE id=document_uuid FOR UPDATE;
        SELECT * INTO c FROM public.document_chunks WHERE id=(p_data->>'id')::uuid FOR UPDATE;
        SELECT * INTO v FROM public.document_versions WHERE id=c.version_id;
        IF NOT d.active OR d.latest_version<>v.version_number OR c.status<>'processing' OR c.lease_until<=now()
            OR c.claim_token IS DISTINCT FROM (p_data->>'claim_token')::uuid OR c.content_hash<>p_data->>'content_hash'
            OR c.model_recipe<>p_data->>'model_recipe' THEN RETURN 'false'; END IF;
        error_value:=p_data->>'error';
        IF error_value IS NULL THEN
            vector_value:=(p_data->>'vector')::extensions.vector(384);
            IF vector_value IS NULL OR abs(extensions.vector_norm(vector_value)-1)>0.001 THEN
                RAISE EXCEPTION 'invalid_vector' USING ERRCODE='22023';
            END IF;
        ELSIF error_value NOT IN ('model_not_installed','model_checksum_failed','dependencies_missing',
            'invalid_vector','invalid_input','input_too_long','inference_failed') THEN
            RAISE EXCEPTION 'invalid_error' USING ERRCODE='22023';
        END IF;
        UPDATE public.document_chunks SET status=CASE WHEN error_value IS NULL THEN 'completed' ELSE 'failed' END,
            error=error_value,embedding=vector_value,embedding_content_hash=CASE WHEN error_value IS NULL THEN content_hash END,
            retry_at=now()+interval '30 seconds',claim_token=NULL,lease_until=NULL WHERE id=c.id;
        IF error_value IS NOT NULL AND c.attempts>=3 THEN
            UPDATE public.document_versions SET status='failed',error=error_value WHERE id=v.id;
        END IF;
        IF NOT EXISTS(SELECT 1 FROM public.document_chunks WHERE version_id=v.id AND status<>'completed') THEN
            UPDATE public.document_versions SET status='completed',error=NULL WHERE id=v.id;
            UPDATE public.documents SET published_version_id=v.id,title=v.title WHERE id=d.id;
        END IF;
        RETURN 'true';
    ELSIF p_operation='search' THEN
        vector_value:=(p_data->>'vector')::extensions.vector(384);
        IF vector_value IS NULL OR abs(extensions.vector_norm(vector_value)-1)>0.001 THEN RAISE EXCEPTION 'invalid_vector' USING ERRCODE='22023'; END IF;
        SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (
            SELECT a.id AS document_id,z.id AS version_id,z.version_number,x.id AS chunk_id,z.title,x.section,
                x.start_line,x.end_line,x.text,1-(x.embedding <=> vector_value) AS similarity
            FROM public.document_chunks x JOIN public.documents a ON a.id=x.document_id
            JOIN public.document_versions z ON z.id=x.version_id
            WHERE a.tenant_id=p_tenant_id AND a.room_id=ANY(p_room_ids) AND a.active
                AND a.published_version_id=z.id AND z.status='completed' AND x.status='completed'
                AND x.embedding_content_hash=x.content_hash AND x.model_recipe=p_data->>'model_recipe'
                AND (p_data->>'document_id' IS NULL OR a.id=(p_data->>'document_id')::uuid)
            ORDER BY x.embedding <=> vector_value,x.id LIMIT least(greatest((p_data->>'limit')::integer,1),20)
        ) q;
        RETURN result;
    END IF;
    SELECT * INTO d FROM public.documents WHERE id=(p_data->>'document_id')::uuid AND tenant_id=p_tenant_id
        AND room_id=ANY(p_room_ids) FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
    IF p_operation='document' THEN RETURN to_jsonb(d);
    ELSIF p_operation='archive' THEN
        IF d.latest_version<>(p_data->>'expected_version')::integer THEN RAISE EXCEPTION 'document_version_conflict' USING ERRCODE='40001'; END IF;
        UPDATE public.documents SET active=false WHERE id=d.id RETURNING * INTO d;
        RETURN to_jsonb(d);
    ELSIF p_operation='versions' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (
            SELECT * FROM public.document_versions WHERE document_id=d.id ORDER BY version_number
            LIMIT least(greatest((p_data->>'limit')::integer,1),50) OFFSET least(greatest((p_data->>'offset')::integer,0),10000)) q;
        RETURN result;
    END IF;
    SELECT * INTO v FROM public.document_versions WHERE id=(p_data->>'version_id')::uuid AND document_id=d.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
    IF p_operation='version' THEN RETURN to_jsonb(v);
    ELSIF p_operation='chunk' THEN
        SELECT * INTO c FROM public.document_chunks WHERE id=(p_data->>'chunk_id')::uuid AND version_id=v.id;
        IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
        RETURN to_jsonb(c)-'embedding'-'claim_token';
    ELSIF p_operation='chunks' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(q)-'embedding'-'claim_token') ,'[]') INTO result FROM (
            SELECT * FROM public.document_chunks WHERE version_id=v.id ORDER BY position
            LIMIT least(greatest((p_data->>'limit')::integer,1),50) OFFSET least(greatest((p_data->>'offset')::integer,0),10000)) q;
        RETURN result;
    END IF;
    RAISE EXCEPTION 'document_invalid_operation' USING ERRCODE='22023';
END;
$$;
REVOKE ALL ON FUNCTION public.document_operation(uuid,uuid[],text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.document_operation(uuid,uuid[],text,jsonb) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;

-- Expect true. Function argument identity does not include vector dimensions.
SELECT to_regprocedure(
    'public.search_memories(uuid,uuid,extensions.vector,integer)'
) IS NOT NULL AS search_function_exists;
